class Dispall(GenericEMSSIMCommand):
    """Dispall command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, obj=None, attr=None, attr_obj=None, runner=None):
        """
        Dispall command.

        :param connection: moler connection to device, terminal when command is executed.
        :param obj: the name of the object that will be displayed
        :param attr: the name of the object attribute that will be displayed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Dispall, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.obj = obj
        self.attr = attr
        self.attr_obj = attr_obj

        self.obj_name = None
        self.attr_name = None
        self.index = None
        self.ret_required = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "disp_all"
        if self.obj:
            cmd = f"{cmd} {self.obj}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_line_table(line)
                self._parse_line_table_value(line)
                self._parse_line_scalar_value(line)
            except ParsingDone:
                pass
        return super(Dispall, self).on_new_line(line, is_full_line)

    _re_parse_line_table = re.compile(r"(?P<ATTR>[\w_-]+)\.(?P<OBJ>[\w_-]+)\s+TABLE$")

    def _parse_line_table(self, line):
        if self._regex_helper.search_compiled(Dispall._re_parse_line_table, line):
            self.obj_name = self._regex_helper.group("OBJ")
            self.attr_name = self._regex_helper.group("ATTR")

            self.current_ret[self._regex_helper.group("OBJ")] = {}
            if not self._regex_helper.group("ATTR") in self.current_ret[self._regex_helper.group("OBJ")]:
                self.current_ret[self._regex_helper.group("OBJ")][self._regex_helper.group("ATTR")] = {}
            self.current_ret[self._regex_helper.group("OBJ")][self._regex_helper.group("ATTR")]["type"] = "table"
            self.current_ret[self._regex_helper.group("OBJ")][self._regex_helper.group("ATTR")]["value"] = []
            raise ParsingDone

    _re_parse_line_table_value = re.compile(r"\[(?P<INDEX>\d+)\]:\s+(?P<PARAM>\S+)\s+(?P<VALUE>\S|\S.*\S)$")

    def _parse_line_table_value(self, line):
        if self.obj_name and self._regex_helper.search_compiled(Dispall._re_parse_line_table_value, line):
            if not self.index == self._regex_helper.group("INDEX"):
                self.index = self._regex_helper.group("INDEX")
                self.current_ret[self.obj_name][self.attr_name]["value"].append({})

            self.current_ret[self.obj_name][self.attr_name]["value"][int(self._regex_helper.group("INDEX"))][
                self._regex_helper.group("PARAM")
            ] = self._regex_helper.group("VALUE")

            raise ParsingDone

    _re_parse_line_scalar_value = re.compile(r"(?P<ATTR>[\w_-]+)\.(?P<OBJ>[\w_-]+)\s+(?P<VALUE>\S|\S.*\S)$")

    def _parse_line_scalar_value(self, line):
        if self._regex_helper.search_compiled(Dispall._re_parse_line_scalar_value, line):
            if not self._regex_helper.group("OBJ") in self.current_ret.keys():
                self.current_ret[self._regex_helper.group("OBJ")] = {}
            if not self._regex_helper.group("ATTR") in self.current_ret[self._regex_helper.group("OBJ")].keys():
                self.current_ret[self._regex_helper.group("OBJ")][self._regex_helper.group("ATTR")] = {}
            self.current_ret[self._regex_helper.group("OBJ")][self._regex_helper.group("ATTR")]["type"] = "scalar"
            self.current_ret[self._regex_helper.group("OBJ")][self._regex_helper.group("ATTR")]["value"] = self._regex_helper.group("VALUE")
            raise ParsingDone


